package cl.ipvg.georegistro;
import android.hardware.*;import android.os.Bundle;import android.widget.TextView;import androidx.appcompat.app.AppCompatActivity;import java.util.*;
public class SensorActivity extends AppCompatActivity implements SensorEventListener{TextView e,x,y,z;SensorManager sm;Sensor ac;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_sensor);e=findViewById(R.id.tvSensorEstado);x=findViewById(R.id.tvSensorX);y=findViewById(R.id.tvSensorY);z=findViewById(R.id.tvSensorZ);sm=(SensorManager)getSystemService(SENSOR_SERVICE);ac=sm.getDefaultSensor(Sensor.TYPE_ACCELEROMETER);if(ac==null)e.setText("Este dispositivo no tiene acelerómetro.");}protected void onResume(){super.onResume();if(ac!=null)sm.registerListener(this,ac,SensorManager.SENSOR_DELAY_NORMAL);}protected void onPause(){super.onPause();if(ac!=null)sm.unregisterListener(this);}public void onSensorChanged(SensorEvent v){float a=v.values[0],b=v.values[1],c=v.values[2];x.setText(String.format(Locale.US,"X: %.2f",a));y.setText(String.format(Locale.US,"Y: %.2f",b));z.setText(String.format(Locale.US,"Z: %.2f",c));e.setText(Math.abs(Math.abs(a)+Math.abs(b)+Math.abs(c)-9.8)>2?"Estado: Movimiento detectado":"Estado: Dispositivo estable");}public void onAccuracyChanged(Sensor s,int a){}}